<template><div class="page-container"><div class="page-header"><div><h2>官方公文流转系统（OA）</h2><p>公文发起、逐级审批、退回与催办</p></div><div><span>当前用户</span><el-input-number v-model="userId" :min="1"/><el-button @click="load">刷新</el-button><el-button type="primary" @click="visible=true">发起公文</el-button></div></div>
<el-tabs v-model="tab"><el-tab-pane label="我发起的" name="mine"><el-table :data="mine"><el-table-column prop="title" label="标题"/><el-table-column prop="docType" label="类型"/><el-table-column prop="currentApproverId" label="当前审批人"/><el-table-column label="状态"><template #default="s"><el-tag :type="statusType[s.row.status]">{{ statusText[s.row.status] }}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link @click="showHistory(s.row)">审批记录</el-button><el-button link type="warning" :disabled="s.row.status!==0" @click="remind(s.row)">催办</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane :label="`待我审批 (${pending.length})`" name="pending"><el-table :data="pending"><el-table-column prop="title" label="标题"/><el-table-column prop="docType" label="类型"/><el-table-column prop="content" label="正文" show-overflow-tooltip/><el-table-column prop="initiatorId" label="发起人"/><el-table-column label="操作" width="230"><template #default="s"><el-button link type="success" @click="approve(s.row,'同意')">同意</el-button><el-button link type="danger" @click="approve(s.row,'拒绝')">拒绝</el-button><el-button link type="warning" @click="approve(s.row,'退回')">退回</el-button><el-button link @click="showHistory(s.row)">记录</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs>
<el-dialog v-model="visible" title="发起公文" width="620"><el-form label-width="90"><el-form-item label="标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="公文类型"><el-select v-model="form.docType"><el-option v-for="v in ['会签','请示','请假','报告']" :key="v" :value="v"/></el-select></el-form-item><el-form-item label="正文"><el-input v-model="form.content" type="textarea" :rows="7"/></el-form-item><el-form-item label="审批链"><el-input v-model="chain" placeholder="按顺序填写用户ID，如：2,3,4"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="start">提交审批</el-button></template></el-dialog>
<el-dialog v-model="historyVisible" title="审批记录"><el-timeline><el-timeline-item v-for="h in history" :key="h.approvalId" :timestamp="h.approvalTime"><b>{{ h.approverId }}：{{ h.action }}</b><p>{{ h.opinion||'无审批意见' }}</p></el-timeline-item></el-timeline><el-empty v-if="!history.length" description="暂无审批记录"/></el-dialog></div></template>
<script setup>import{onMounted,reactive,ref,watch}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{documentAPI}from'@/api/getData.js';const userId=ref(1),tab=ref('mine'),mine=ref([]),pending=ref([]),visible=ref(false),historyVisible=ref(false),history=ref([]),chain=ref('2'),form=reactive({title:'',docType:'请示',content:''});const statusText=['审批中','已通过','已拒绝','已退回'],statusType=['warning','success','danger','info'];const load=async()=>{const[a,b]=await Promise.all([documentAPI.initiated(userId.value),documentAPI.pending(userId.value)]);if(a&&a!==-1)mine.value=a.data||[];if(b&&b!==-1)pending.value=b.data||[]};const start=async()=>{const ids=chain.value.split(',').map(v=>Number(v.trim())).filter(Number.isInteger);const r=await documentAPI.start({...form,initiatorId:userId.value,approvalChain:JSON.stringify(ids)});if(r&&r!==-1){ElMessage.success('公文已进入审批流程');visible.value=false;load()}};const approve=async(row,action)=>{const{value}=await ElMessageBox.prompt(`请输入“${action}”意见`,'审批意见',{inputValue:action});const r=await documentAPI.approve(row.docId,{approverId:userId.value,action,opinion:value});if(r&&r!==-1){ElMessage.success('审批完成');load()}};const remind=async row=>{const r=await documentAPI.remind(row.docId);if(r&&r!==-1)ElMessage.success('催办通知已发送')};const showHistory=async row=>{const r=await documentAPI.history(row.docId);if(r&&r!==-1){history.value=r.data||[];historyVisible.value=true}};watch(userId,load);onMounted(load);</script>
<style scoped>.page-container{padding:24px;background:#f5f7fa;min-height:100vh}.page-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.page-header h2{margin:0}.page-header p{color:#909399}.page-header>div:last-child{display:flex;align-items:center;gap:8px}.el-tabs{background:white;padding:16px 20px}</style>
